import React from 'react'
import { Form, Input, InputNumber, Switch } from '@pimcore/studio-ui-bundle/components'
import { useTranslation } from '@pimcore/studio-ui-bundle/app'
import { type OperatorConfigModalProps } from '../../dynamic-type-operator-abstract'
import { type SubstringAttributes } from './dynamic-type-operator-substring'
import { OperatorModal } from '../../components/operator-modal'

export const SubstringConfigModal = (props: OperatorConfigModalProps<SubstringAttributes>): React.JSX.Element => {
  const { t } = useTranslation()

  return (
    <OperatorModal
      { ...props }
      initialValues={ { start: 0, ellipses: false } }
    >
      {() => (
        <>
          <Form.Item
            label={ t('data-hub.label') }
            name="label"
          >
            <Input />
          </Form.Item>
          <Form.Item
            label={ t('data-hub.operator.start') }
            name="start"
          >
            <InputNumber
              min={ 0 }
              style={ { width: '100%' } }
            />
          </Form.Item>
          <Form.Item
            label={ t('data-hub.operator.length') }
            name="length"
          >
            <InputNumber
              min={ 0 }
              style={ { width: '100%' } }
            />
          </Form.Item>
          <Form.Item
            name="ellipses"
          >
            <Switch labelRight={ t('data-hub.operator.ellipses') } />
          </Form.Item>
        </>
      )}
    </OperatorModal>
  )
}
